PRIVACY = ("Gizlilik beyanı", "Son güncelleme: Kasım 2026", [
 ("Biz kimiz?", ["Sealcleaning Groenonderhoud en Aanleg, Romboutslaan 582, 3312 KP Dordrecht (KvK 83078665), bu beyanda açıklanan kişisel verilerin işlenmesinden sorumludur. Sorularınız için sealcleaningaanleg@gmail.com adresine e-posta gönderebilir veya 078 204 95 17 numarasını arayabilirsiniz."]),
 ("Hangi verileri neden işliyoruz?", ["Bize iletişim formu, e-posta, telefon veya WhatsApp üzerinden kendiniz verdiğiniz verileri işleriz:",
   ("ul", ["ad, telefon numarası ve e-posta adresi;", "posta kodu ve yaşadığınız yer;", "talebinizin açıklaması ve varsa fotoğraflar veya diğer ekler;", "3B tasarımcıdan gönderdiğiniz seçimler ve ölçüler."]),
   "Bu verileri talebinizi değerlendirmek, sizinle iletişime geçmek, teklif hazırlamak ve işi yürütmek için kullanırız. Bir iş verildiğinde teklifi, anlaşmaları ve faturaları da saklarız.",
   "Kurumsal talepleri ve bizimle çalışmak isteyen ustaların başvurularını yalnızca o talebi veya başvuruyu değerlendirmek için kullanırız."]),
 ("Formlar nasıl çalışır?", ["Bu web sitesindeki formlar FormSubmit form hizmeti üzerinden gönderilir. Bu hizmet mesajınızı, varsa eklerle birlikte, e-posta ile bizim posta kutumuza iletir. Hem bu hizmet hem de e-posta hizmetimiz verileri Avrupa Ekonomik Alanı dışında işleyebilir.",
   "Web sitesi üzerinden gönderim başarısız olursa, talebinizi kendi e-posta programınızla gönderebilir ya da bizi arayabilir veya WhatsApp mesajı gönderebilirsiniz. Bu durumda fotoğraf ekleyip eklemeyeceğinize siz karar verirsiniz."]),
 ("3B tasarımcı", ["3B tasarımcıda yaptığınız seçimler yalnızca kendi tarayıcınızda saklanır. Bunlar ancak siz bir talebe ekleyerek gönderdiğinizde bize ulaşır. \"Opnieuw beginnen\" (Yeniden başla) düğmesiyle ya da tarayıcınızdaki bu siteye ait verileri silerek temizleyebilirsiniz."]),
 ("Çerezler ve ölçüm", ["Bu web sitesi izleme veya reklam çerezi ve analiz yazılımı kullanmaz. Yazı tipleri ve görseller kendi web sitemizden gelir. Tasarımınızı saklamak için tarayıcınızın yerel depolamasını kullanırız; bu, o işlev için gereklidir ve sizi izlemeye yönelik değildir."]),
 ("Barındırma", ["Web sitesi GitHub Pages üzerinden sunulur. Bir sayfa istendiğinde barındırma sağlayıcısı, siteyi gösterebilmek ve güvenliğini sağlayabilmek için IP adresiniz gibi teknik verileri işleyebilir."]),
 ("Başkalarıyla paylaşım", ["Verilerinizi satmayız. Bunları yalnızca talebinizin veya işinizin yürütülmesi için gerekli taraflarla, örneğin yukarıda anılan hizmetler ve gerekirse bir malzeme tedarikçisiyle paylaşırız. Ayrıca yasal olarak zorunlu olduğumuzda veri paylaşırız."]),
 ("Verileri ne kadar saklarız?", ["Verileri, talebinizin ve olası bir işin yürütülmesi için gerekenden uzun süre saklamayız. Yasal olarak saklamamız gereken verileri, örneğin faturaları, yasanın gerektirdiği süre boyunca saklarız."]),
 ("Proje fotoğrafları", ["Web sitesinde gösterdiğimiz işlerimizin fotoğraflarında plakaları ve kapı numaralarını gizleriz."]),
 ("Haklarınız", ["Hangi verilerinizin bizde olduğunu sorabilir, düzeltilmesini veya silinmesini isteyebilir, kullanımına itiraz edebilir ve verilerinizin aktarılmasını talep edebilirsiniz. Bunun için bize e-posta gönderin. Birlikte çözüme ulaşamazsak, Hollanda Kişisel Verileri Koruma Kurumu'na (Autoriteit Persoonsgegevens, autoriteitpersoonsgegevens.nl) şikâyette bulunabilirsiniz."]),
 ("Değişiklikler", ["Çalışma şeklimiz veya web sitesi değiştiğinde bu beyanı güncelleriz. Yukarıdaki tarih, bunun en son ne zaman yapıldığını gösterir."]),
])
TERMS = ("Genel koşullar", "Son güncelleme: Kasım 2026", [
 ("1. Taraflar ve uygulama alanı", ["Bu koşullar, Sealcleaning Groenonderhoud en Aanleg (ticari adı Sealcleaning), Romboutslaan 582, 3312 KP Dordrecht, KvK 83078665, KDV no. NL003773849B79 (\"Sealcleaning\") ile müşterisi arasındaki her teklif, iş ve sözleşme için geçerlidir; kapsam: bahçe bakımı, bahçe yapımı, zemin kaplama, çitler ve ilgili işler ile olası malzeme satışı. Bu sürüm tarihlidir ve bağlayıcı bir tekliften önce müşteriye sunulur."]),
 ("2. İş ve belgelerin sıralaması", ["Bağlayıcı olmayan bir ön görüşme, keşif veya tasarım henüz bir iş değildir. İş, müşterinin teklifi yazılı olarak (veya bunun için öngörülen dijital yolla) onaylamasıyla kurulur. Çelişki halinde özel, imzalı teklif/iş onayı bu genel koşulların önüne geçer; sapmalar yalnızca yazılı olarak kararlaştırılır."]),
 ("3. Teklif ve geçerlilik", ["Teklifte işler, miktarlar, malzemeler, nelerin dahil ve hariç olduğu, bilinen belirsizlikler ve bir geçerlilik süresi belirtilir. Teklif, müşteri kabul edene kadar bağlayıcı değildir; belirtilen geçerlilik süresinden sonra Sealcleaning teklifi, örneğin malzeme fiyatları değiştiğinde, gözden geçirebilir."]),
 ("4. Fiyat türü ve KDV", ["Teklifte sabit fiyat, tahmini fiyat veya saat esaslı (fiilen harcanan saat) fiyat geçerli olup olmadığı belirtilir. İşçilik, malzeme, nakliye, atık uzaklaştırma ve kiralama, aksi açıkça belirtilmedikçe teklifte ayrı kalemler olarak yer alır. Tüketici fiyatları geçerli KDV oranı dahil gösterilir; oran kalem bazında değerlendirilir."]),
 ("5. Ölçüm ve müşteri bilgisi", ["Müşteri, bahçe ve durum hakkında bilinen, ilgili bilgileri (ölçüler, zemin, engeller, bilinen kadarıyla kablo/borular) paylaşır. Sealcleaning bu bilgileri, özenli bir meslek işletmesinden makul olarak beklenebilecek ölçüde kontrol eder ve fark edilebilir hatalar veya risklerde uyarır; ancak müşterinin paylaşmadığı ve makul olarak fark edilemeyecek yanlış veya eksik bilgilerin sonuçlarından sorumlu değildir."]),
 ("6. Tasarım ve görselleştirme", ["2B/3B tasarım, eskiz veya görselleştirme (örneğin çevrimiçi tasarımcı aracılığıyla) seçim yapmaya yardımcı bir araçtır; kesin bir teknik çizim, temel hesabı, izin denetimi veya tam ölçü garantisi değildir. Gerçek ölçüler, renkler ve malzemeler uygulama sırasında kontrol edilir."]),
 ("7. Parsel sınırı ve ortak iş", ["Müşteri istenen parsel sınırını ve varsa komşularla anlaşmaları belirtir. Ortak bir işte (örneğin ortak bir çit) Sealcleaning, kapsam ve maliyet paylaşımı konusunda ilgili taraflarla anlaşma yapar; Sealcleaning parsel sınırını hukuken bağlayıcı olarak belirlemez ve Sealcleaning'e yazılı olarak bildirilmemiş komşular arası anlaşmalardan sorumlu değildir."]),
 ("8. İzin ve ruhsat", ["İşe bağlı olarak izin veya bildirim gerekebilir (örneğin daha yüksek bir çit veya yapı için). Müşteri ve Sealcleaning bunu kimin kontrol edeceğini önceden konuşur; belirli bir yüksekliğin altındaki bir çit her durumda otomatik olarak izinsiz değildir — kurallar belediyeye ve yere göre değişir. Güncel kontrol için Omgevingsloket/IPLO'ya bakın. Sealcleaning bir tasarımla hukuki onay vermez."]),
 ("9. Hazırlık ve erişim", ["Taraflar kimin neyi hazırlayacağını kararlaştırır: çalışma alanına serbest erişim, gerekirse su/elektrik, park/boşaltma imkânı ve güvenli bir çalışma alanı. Kısıtlı erişim nedeniyle ek emek önceden konuşulur ve gerekirse ayrıca fiyatlandırılır — sonradan sürpriz bir ek ücret olarak otomatik değil."]),
 ("10. Kazı ve gizli koşullar", ["Makineyle toprak işlerinde ilgili kablo/boru bilgileri önceden kontrol edilir (uygun olduğunda KLIC bildirimi). İş sırasında beklenmedik engeller kayda geçirilir ve bunlara dayanarak iş sürdürülmeden veya değiştirilmeden önce müşteriyle konuşulur."]),
 ("11. Tehlikeli veya bilinmeyen durum", ["Asbest şüphesi, ciddi toprak kirliliği, tehlikeli kablo/borular veya Sealcleaning'in yetkisi dışındaki işlerde, o kısımdaki iş güvenli şekilde durdurulur, kayda geçirilir ve görüşülerek uygun bir sonraki adım (örneğin bir uzman) belirlenir. Bu, görüşülmeden otomatik bir ek iş faturası doğurmaz."]),
 ("12. Müşterinin kendi malzemesi", ["Müşteri kendi malzemesiyle \"yalnızca montaj\" seçerse, sistem, marka/tip, miktarlar ve uygunluk önceden kontrol edilir. Sealcleaning fark edilebilir uygunsuzluklarda uyarır; ancak müşterinin kendisinin temin edip teslim ettiği malzemedeki kusurlardan sorumlu değildir."]),
 ("13. Sealcleaning'in tedarik ettiği malzeme", ["Müşteri malzemeyi Sealcleaning aracılığıyla seçerse, ürün/sistem, teslimat ve maliyetler önceden kaydedilir. Alternatif bir ürün yalnızca müşteriyle görüşüp onay alındıktan sonra teslim edilir; bir tedarik sorununda sessizce değiştirilmez."]),
 ("14. Planlama ve koşullar", ["Tercih edilen bir tarih, Sealcleaning onaylayana kadar kesinleşmiş bir randevu değildir. Planlamadaki değişiklikler (örneğin hava durumu veya malzeme teslim süresi nedeniyle) mümkün olan en kısa sürede bildirilir. Normal hava etkisi, iletişim kurmadan sınırsız erteleme için bir bahane değildir."]),
 ("15. Ek ve eksik iş", ["İşteki değişiklikler veya ilk teklifte yer almayan işler önceden konuşulur ve gerekirse ayrıca teklif edilir; makul olarak mümkün olduğunda uygulamadan önce müşterinin onayı alınır. Önceden kararlaştırılmış tahmini fiyatta, önemli bir aşım olasılığı doğduğunda Sealcleaning zamanında bilgi verir."]),
 ("16. Uygulama ve alt yükleniciler", ["Sealcleaning işleri, bir meslek işletmesinden beklenen özenle yürütür; gerekirse Sealcleaning'in gözetiminde alt yükleniciler veya kiralanan ustalar görevlendirilebilir. Müşteri için muhatap Sealcleaning olarak kalır."]),
 ("17. Atık ve çalışma alanı", ["Bahçe atığı, moloz veya diğer artıkların kimin tarafından uzaklaştırılacağı ve bunun fiyata dahil olup olmadığı önceden kararlaştırılır. Teklife zaten dahil edilmiş uzaklaştırma ayrıca tekrar ücretlendirilmez. Sealcleaning, iş bittikten sonra çalışma alanını kararlaştırılan kapsam içinde derli toplu bırakır."]),
 ("18. Teslim", ["İş bittikten sonra sonuç müşteriyle birlikte gözden geçirilir ve olası dikkat noktaları kayda geçirilir. Teslim, daha sonra ortaya çıkan ve makul olarak daha önce fark edilemeyen kusurlar için yasal haklardan feragat anlamına gelmez."]),
 ("19. Bakım ve canlı yeşil", ["Teslim edilen bitkilerde Sealcleaning uygun bakım tavsiyesi verir. Bitki kaybının birden fazla nedeni olabilir (örneğin yetersiz sulama, toprak yapısı veya mevsim etkileri); Sealcleaning bir şikâyette olası nedeni değerlendirir ve bitki kaybını otomatik olarak her türlü garantinin dışında tutmaz."]),
 ("20. Garanti ve şikâyetler", ["Sealcleaning yasal tüketici haklarını, teslim edilen malzemedeki olası üretici garantisini ve ayrıca kayda geçirilmiş olası bir kendi iş garantisini birbirinden ayırır. Şikâyetlerinizi iletişim formu, telefon veya e-posta ile bildirebilirsiniz; Sealcleaning şikâyeti makul bir süre içinde ele alır ve görüşerek uygun bir çözüm arar."]),
 ("21. Fatura ve ödeme", ["Faturalar doğru ve yasal fatura gerekliliklerine uygun düzenlenir ve yazılı olarak aksi kararlaştırılmadıkça faturada belirtilen süre içinde ödenmelidir. Ödeme süresi, olası peşinat ve ödeme şekli iş verilmeden önce kayda geçirilir. Geç ödemede ihtar, faiz ve tahsilat masrafları hakkındaki yasal kurallar geçerlidir."]),
 ("22. Cayma, iptal ve fesih", ["Uzaktan veya satış yeri dışında yapılan sözleşmelerde yasal bir cayma süresi uygulanabilir; Sealcleaning müşteriyi bu konuda bilgilendirir ve yasal olarak gerekli olduğunda bundan yararlanmak için uygun bir yol sunar. Müşteri işin bu süre içinde başlamasını isterse, bunun için önceden açıkça onay istenir. Planlanmış bir işin iptali zamanında bildirilmelidir; sipariş edilmiş malzeme gibi yapılmış masraflar faturalanabilir."]),
 ("23. Sorumluluk ve sigorta", ["Sealcleaning işleri özenle yürütür. Hasar sorumluluğu genel olarak hariç tutulmamıştır, ancak bu büyüklük ve nitelikteki bir işletme için yasal olarak makul ve olağan olanla sınırlıdır. Zorunlu tüketici hakları bu koşullarla sınırlandırılmaz."]),
 ("24. Gizlilik, uyuşmazlıklar ve değişiklikler", ["Kişisel verilerin işlenmesi için gizlilik beyanımıza bakın. Proje fotoğraflarının yayımlanmasına izin vermek, bir teklifi onaylamaktan farklı bir şeydir. Bu koşullara Hollanda hukuku uygulanır; uyuşmazlık halinde önce karşılıklı bir çözüm aranır. Bu koşulların daha sonraki bir sürümü, daha önce onaylanmış ve devam eden bir işi geriye dönük olarak değiştirmez."]),
])
